import { useState, useEffect } from 'react';
import { Search, CheckCircle, XCircle } from 'lucide-react';
import api from '../services/api';
import toast from 'react-hot-toast';

function AdminPayouts() {
  const [payouts, setPayouts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchPayouts = async () => {
      try {
        const res = await api.get('/admin/payouts');
        setPayouts(res.data);
      } catch (error) {
        console.error('Failed to fetch payouts');
      } finally {
        setLoading(false);
      }
    };
    fetchPayouts();
  }, []);

  const filteredPayouts = payouts.filter(payout =>
    payout.user?.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    payout.user?.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleStatusUpdate = async (payoutId, status) => {
    try {
      await api.put(`/admin/payouts/${payoutId}`, { status });
      setPayouts(payouts.map(p => p._id === payoutId ? { ...p, status } : p));
      toast.success(`Payout ${status}`);
    } catch (error) {
      toast.error('Failed to update payout status');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <h1 className="text-3xl font-bold text-gray-900 mb-8">Payout Approvals</h1>

      <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
          <input
            type="text"
            placeholder="Search by user name or email..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
          />
        </div>
      </div>

      {loading ? (
        <div className="text-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto"></div>
        </div>
      ) : (
        <div className="bg-white rounded-lg shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50">
                <tr>
                  <th className="text-left py-3 px-6 text-sm font-medium text-gray-600">User</th>
                  <th className="text-left py-3 px-6 text-sm font-medium text-gray-600">Amount</th>
                  <th className="text-left py-3 px-6 text-sm font-medium text-gray-600">Method</th>
                  <th className="text-left py-3 px-6 text-sm font-medium text-gray-600">Date</th>
                  <th className="text-left py-3 px-6 text-sm font-medium text-gray-600">Status</th>
                  <th className="text-left py-3 px-6 text-sm font-medium text-gray-600">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {filteredPayouts.map((payout) => (
                  <tr key={payout._id} className="hover:bg-gray-50">
                    <td className="py-4 px-6">
                      <div>
                        <p className="text-gray-900 font-medium">{payout.user?.name}</p>
                        <p className="text-sm text-gray-500">{payout.user?.email}</p>
                      </div>
                    </td>
                    <td className="py-4 px-6 text-gray-900 font-medium">${payout.amount.toFixed(2)}</td>
                    <td className="py-4 px-6 text-gray-600 capitalize">{payout.method}</td>
                    <td className="py-4 px-6 text-gray-600">
                      {new Date(payout.createdAt).toLocaleDateString()}
                    </td>
                    <td className="py-4 px-6">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        payout.status === 'completed' ? 'bg-green-100 text-green-800' :
                        payout.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-red-100 text-red-800'
                      }`}>
                        {payout.status}
                      </span>
                    </td>
                    <td className="py-4 px-6">
                      {payout.status === 'pending' && (
                        <div className="flex gap-2">
                          <button
                            onClick={() => handleStatusUpdate(payout._id, 'completed')}
                            className="p-1 text-green-600 hover:text-green-800"
                            title="Approve"
                          >
                            <CheckCircle className="h-5 w-5" />
                          </button>
                          <button
                            onClick={() => handleStatusUpdate(payout._id, 'rejected')}
                            className="p-1 text-red-600 hover:text-red-800"
                            title="Reject"
                          >
                            <XCircle className="h-5 w-5" />
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminPayouts;
