import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, Clock, CheckCircle } from 'lucide-react';
import api from '../services/api';
import toast from 'react-hot-toast';

function TaskDetail() {
  const { id } = useParams();
  const [task, setTask] = useState(null);
  const [loading, setLoading] = useState(true);
  const [proof, setProof] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const fetchTask = async () => {
      try {
        const res = await api.get(`/tasks/${id}`);
        setTask(res.data);
      } catch (error) {
        console.error('Failed to fetch task');
      } finally {
        setLoading(false);
      }
    };
    fetchTask();
  }, [id]);

  const handleSubmitProof = async (e) => {
    e.preventDefault();
    if (!proof.trim()) return;

    setSubmitting(true);
    try {
      await api.post(`/tasks/${id}/submit`, { proof });
      toast.success('Proof submitted successfully!');
      setProof('');
    } catch (error) {
      toast.error('Failed to submit proof');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  if (!task) {
    return (
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <p className="text-gray-500">Task not found</p>
        <Link to="/tasks" className="text-indigo-600 hover:text-indigo-800">Back to tasks</Link>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <Link to="/tasks" className="inline-flex items-center text-indigo-600 hover:text-indigo-800 mb-6">
        <ArrowLeft className="h-4 w-4 mr-1" />
        Back to Tasks
      </Link>

      <div className="bg-white rounded-lg shadow-sm p-8">
        <div className="flex flex-wrap items-center gap-3 mb-4">
          <span className="px-3 py-1 bg-indigo-100 text-indigo-800 rounded-full text-sm font-medium">
            {task.category}
          </span>
          <span className="px-3 py-1 bg-green-100 text-green-800 rounded-full text-sm font-medium">
            ${task.reward.toFixed(2)} reward
          </span>
          <span className={`px-3 py-1 rounded-full text-sm font-medium ${
            task.status === 'available' ? 'bg-green-100 text-green-800' :
            task.status === 'claimed' ? 'bg-yellow-100 text-yellow-800' :
            'bg-gray-100 text-gray-800'
          }`}>
            {task.status}
          </span>
        </div>

        <h1 className="text-3xl font-bold text-gray-900 mb-4">{task.title}</h1>
        <p className="text-gray-600 mb-6 leading-relaxed">{task.description}</p>

        <div className="bg-gray-50 rounded-lg p-6 mb-8">
          <h3 className="text-lg font-semibold text-gray-900 mb-3">Requirements</h3>
          <ul className="list-disc list-inside space-y-2 text-gray-700">
            {task.requirements.map((req, index) => (
              <li key={index}>{req}</li>
            ))}
          </ul>
        </div>

        {task.status === 'claimed' && (
          <div className="bg-indigo-50 border border-indigo-200 rounded-lg p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Submit Proof</h3>
            <form onSubmit={handleSubmitProof}>
              <textarea
                value={proof}
                onChange={(e) => setProof(e.target.value)}
                rows="4"
                placeholder="Describe how you completed the task or provide links to proof..."
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent mb-4"
              />
              <button
                type="submit"
                disabled={submitting || !proof.trim()}
                className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 font-medium transition disabled:bg-gray-300"
              >
                {submitting ? 'Submitting...' : 'Submit Proof'}
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
}

export default TaskDetail;
