import { useState, useEffect } from 'react';
import { Users, Link2, Copy, Share2, DollarSign } from 'lucide-react';
import api from '../services/api';
import toast from 'react-hot-toast';

function Referrals() {
  const [stats, setStats] = useState({
    totalReferrals: 0,
    activeReferrals: 0,
    earnings: 0,
    referralCode: ''
  });
  const [referrals, setReferrals] = useState([]);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const fetchReferralData = async () => {
      try {
        const res = await api.get('/referrals');
        setStats(res.data.stats);
        setReferrals(res.data.referrals);
      } catch (error) {
        console.error('Failed to fetch referral data');
      }
    };
    fetchReferralData();
  }, []);

  const referralLink = `${window.location.origin}/register?ref=${stats.referralCode}`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(referralLink);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <h1 className="text-3xl font-bold text-gray-900 mb-8">Referral Program</h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Total Referrals</p>
              <p className="text-2xl font-bold text-gray-900">{stats.totalReferrals}</p>
            </div>
            <Users className="h-8 w-8 text-indigo-600" />
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Active Referrals</p>
              <p className="text-2xl font-bold text-gray-900">{stats.activeReferrals}</p>
            </div>
            <Users className="h-8 w-8 text-green-600" />
          </div>
        </div>
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Referral Earnings</p>
              <p className="text-2xl font-bold text-gray-900">${stats.earnings.toFixed(2)}</p>
            </div>
            <DollarSign className="h-8 w-8 text-green-600" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm p-8 mb-8">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">Your Referral Code</h2>
        <div className="flex flex-col sm:flex-row gap-4">
          <div className="flex-1 bg-gray-50 rounded-lg p-4 font-mono text-lg text-center">
            {stats.referralCode}
          </div>
          <button
            onClick={() => {
              navigator.clipboard.writeText(stats.referralCode);
              toast.success('Code copied!');
            }}
            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium transition"
          >
            <Copy className="h-4 w-4 inline mr-1" />
            Copy Code
          </button>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm p-8 mb-8">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">Share Your Link</h2>
        <div className="flex flex-col sm:flex-row gap-4">
          <input
            type="text"
            readOnly
            value={referralLink}
            className="flex-1 px-4 py-2 bg-gray-50 border border-gray-300 rounded-lg"
          />
          <button
            onClick={copyToClipboard}
            className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium transition"
          >
            <Share2 className="h-4 w-4 inline mr-1" />
            {copied ? 'Copied!' : 'Copy Link'}
          </button>
        </div>
        <p className="text-sm text-gray-600 mt-3">
          Share this link with friends. You'll earn 10% of their first task reward!
        </p>
      </div>

      <div className="bg-white rounded-lg shadow-sm p-8">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">Your Referrals</h2>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-200">
                <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Name</th>
                <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Email</th>
                <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Joined</th>
                <th className="text-left py-3 px-4 text-sm font-medium text-gray-600">Status</th>
              </tr>
            </thead>
            <tbody>
              {referrals.length > 0 ? (
                referrals.map((ref) => (
                  <tr key={ref._id} className="border-b border-gray-100">
                    <td className="py-3 px-4 text-gray-900">{ref.name}</td>
                    <td className="py-3 px-4 text-gray-600">{ref.email}</td>
                    <td className="py-3 px-4 text-gray-600">{new Date(ref.joinedAt).toLocaleDateString()}</td>
                    <td className="py-3 px-4">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        ref.active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                      }`}>
                        {ref.active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" className="py-8 text-center text-gray-500">
                    No referrals yet. Share your link to get started!
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default Referrals;
